#[test]
fn sqlite_snapshot_en1999_controlled_output_has_exact_wire_and_real_interior_admission(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let limits=&corpus["controlledOutput"];let count=limits["textBytes"].as_u64().unwrap() as usize;let after=limits["cancelAfter"].as_u64().unwrap() as usize;let tiny=limits["tinyBytes"].as_u64().unwrap() as usize;let mut s=fixture();s.materials[0].designation="x".repeat(count);let rows=project(&s).tables.iter().map(|table|table.rows.len()).sum();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let expected=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<En1999Snapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<En1999Snapshot as store::ArtifactDsl>::print_dsl(&s))};let actual=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert!(actual==expected,"controlled owner wire differs");let bytes=match &expected{store::io_schema::IoPayload::Binary(v)=>v.len(),store::io_schema::IoPayload::Text(v)=>v.len()};assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:bytes,..SqliteDatabaseLimits::default()})).unwrap()==expected);let mut interior=false;let error=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |event|{let stop=event.phase==SqliteSnapshotPhase::EncodeNative&&event.total>after&&event.completed>=after&&event.completed<event.total;interior|=stop;!stop},SqliteDatabaseLimits::default())).unwrap_err();assert!(interior&&error.kind == semio_framework_value::ValueRefusalKind::Canceled,"{error}");assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:rows,..SqliteDatabaseLimits::default()})).unwrap()==expected);for budget in[SqliteDatabaseLimits{max_rows:rows-1,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_file_bytes:bytes-1,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_value_bytes:tiny,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_rows:0,..SqliteDatabaseLimits::default()}]{assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,budget)).is_err());}assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
